function chargingLoop(gain, cost) {
  const n = gain.length;
  for (let s = 0; s < n; s++) {
    let tank = 0, ok = true;
    for (let k = 0; k < n && ok; k++) {
      const i = (s + k) % n;
      tank += gain[i] - cost[i];
      if (tank < 0) ok = false;
    }
    if (ok) return s;
  }
  return -1;
}

function chargingLoop(gain, cost) {
  let total = 0, tank = 0, start = 0;
  for (let i = 0; i < gain.length; i++) {
    const delta = gain[i] - cost[i];
    total += delta;
    tank += delta;
    if (tank < 0) { start = i + 1; tank = 0; }
  }
  return total < 0 ? -1 : start;
}
